export type ParsedStakeInstruction<
  TProgram extends string = typeof ENVELOPE_STAKE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    user: TAccountMetas[0]
    pool: TAccountMetas[1]
    stakePosition: TAccountMetas[2]
    userSkr: TAccountMetas[3]
    vaultSkr: TAccountMetas[4]
    tokenProgram: TAccountMetas[5]
    systemProgram: TAccountMetas[6]
  }
  data: StakeInstructionData
}

export function parseStakeInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedStakeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 7,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      pool: getNextAccount(),
      stakePosition: getNextAccount(),
      userSkr: getNextAccount(),
      vaultSkr: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getStakeInstructionDataDecoder().decode(instruction.data),
  }
}
